{
  "contract": "TRYPTO",
  "closure": {
    "site_function": "take_marketing",
    "site_call": ".call",
    "functions": [
      "take_marketing",
      "transfer",
      "transferFrom"
    ],
    "justification": "These functions interact with the exposed storage variables _ethBal and marketing_balance."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1
    }
  },
  "phases": {
    "function": "take_marketing",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Tracks the amount of ether in-flight during the callback window.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "marketing_balance + growth_balance + inFlight <= _ethBal",
    "stable_formula": "marketing_balance + growth_balance <= _ethBal",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "marketing_balance + growth_balance <= _ethBal",
    "rule": "The exposure invariant ensures that the sum of marketing_balance and growth_balance, accounting for in-flight ether, does not exceed _ethBal."
  }
}
